// get a point from the lookup table
vec2 get_lut(int i) {
    return texelFetch(iChannel0, ivec2(i, 0), 0).xy;
}

// search the LUT for the closest point to the current fragment
vec2 closest_point(vec2 p) {
    float best_dist = 10.0;
    vec2 best_point = vec2(0.0);
    int best_index = 0;
    for (int i=0; i<LUT_SIZE; i++) {
        vec2 point = get_lut(i);
        float dist = distance(p, point);
        if (dist < best_dist) {
            best_dist = dist;
            best_point = point;
            best_index = i;
        }
    }

    vec2[NUM_POINTS] bezier;
    for (int i=0; i<NUM_POINTS; i++) {
        bezier[i] = get_point(i);
    }

    // This searches between adjacent points on the lookup table to find a more accurate point.
    float interval = 0.5 / float(LUT_SIZE - 1);
    float best_t   = float(best_index) / float(LUT_SIZE - 1);
    while (interval > 0.125 / iResolution.y) {
        for (int i=-2; i<=2; i++) {
            float current_t = best_t + float(i) * interval;
            if (current_t >= 0.0 && current_t <= 1.0) {
                vec2 point = compute_bezier(bezier, current_t);
                float dist = distance(p, point);
                if (dist < best_dist) {
                    best_t = current_t;
                    best_point = point;
                    best_dist = dist;
                }
            }
        }

        interval *= 0.5;
    }

    return best_point;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.y;
    vec2 xy = fragCoord.xy - 0.5;

    float dp =  2.0 / SDF_FREQ;

    vec3 col = vec3(0.1);

    vec2 best_point = closest_point(uv);
    // approximate distance to SDF
    float d = distance(xy, best_point * iResolution.y);
    // use modulo to produce discrete bands
    float z = mod((d - SDF_FREQ * 0.4) / SDF_FREQ, 1.0) / 1.0;
    // v "selects" either the x or y value based on which band we're in
    float v = mix(fragCoord.x, fragCoord.y, step(z, 0.5));
    // use separate offsets into the color gradient depending on 'v'
    float o = mix(-2.0, 3.0, step(z, 0.5));
    // normalize gradient so it looks the same whether or not it's fullscreen
    float l = 0.0033 * 873.0 / iResolution.x;
    // sample into the colormap
    col = step(mod(v, float(LINE_SPACING)), float(LINE_WIDTH)) * spectrum(v * l + o + iTime);

    // apply antialiased black lines between the bands
    col *= smoothstep(0.0, dp * OUTLINE_WIDTH, abs(z - 0.5));
    col *= smoothstep(0.0, dp * OUTLINE_WIDTH, abs((mod(z - 0.5, 1.0)) - 0.5));

    fragColor = vec4(col, 1.0);
    return;
}

// for b spline interpolation
const mat4x4 T = mat4x4(1.0 ,4.0, 1.0, 0.0, -3.0, 0.0, 3.0, 0.0, 3.0, -6.0, 3.0, 0.0, -1.0, 3.0, -3.0, 1.0) / 6.0;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 xy = ivec2(fragCoord.xy);
    ivec2 tex_size = textureSize(iChannel1, 0);

    int cycle_num = iFrame / CYCLE_TIME;
    float interp = float(iFrame % CYCLE_TIME) / float(CYCLE_TIME);

    vec2[NUM_POINTS] points;
    for (int i=0; i<NUM_POINTS; i++) {
        // Generate points for bezier curve
        //  - grab NUM_POINTS  * 4 random vectors from rand texture
        //  - use cubic b-spline interpolation between the 4 sets of NUM_POINTS points
        mat4x2 samples;
        for (int j=0; j<4; j++) {
            // grab numbers from 4 consecutive (wrapping) rows of the rand texture
            //   11 is a magic number to get a good offset for the screenshot :) 
            int row = (11 + j + cycle_num) % tex_size.y;
            samples[j] = texelFetch(iChannel1, ivec2(i % (NUM_POINTS - 0), row), 0).xy * ASPECT;
        }
        points[i] = samples * (T * pow(vec4(interp), vec4(0.0, 1.0, 2.0, 3.0)));
        points[i] -= ASPECT * 0.5;
        points[i] *= 2.0;
        points[i] += ASPECT * 0.5;
    }

    if (xy.y == 0) {
        // write LUT values to row 0
        if (xy.x < LUT_SIZE) {
            float t = float(xy.x) / float(LUT_SIZE - 1);
            fragColor = vec4(compute_bezier(points, t), 0.0, 1.0);
        } else {
            fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        }
    } else if (xy.y == 1 && xy.x < NUM_POINTS) {
        // write locations of bezier nodes to row 1
        fragColor = vec4(points[xy.x], 0.0, 1.0);
    } else {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
    }
}

#define PI 3.14159265
#define TWO_PI (PI * 2.0)
#define spectrum(x) (0.7 + 0.5 * cos(x - vec3(0.0, 1.0, 2.0) * TWO_PI / 3.0))

#define get_point(i) (texelFetch(iChannel0, ivec2(i, 1), 0).xy)
#define ASPECT vec2(16.0/9.0, 1.0)

// speed to move through the different bezier curves
#define CYCLE_TIME 500

// frequency of linear pattern
#define LINE_SPACING  4
// duty cycle of linear pattern
#define LINE_WIDTH    2
// width of black outline between regions
#define OUTLINE_WIDTH 1.0
// width in pixels of SDF bands
#define SDF_FREQ 30.0

// Degree of Bezier curve. Lower this to significantly improve performance.
const int NUM_POINTS = 6;

// Lookup table for computing nearest point. Some artifacts will be visible near
// self intersection points if this is too low.
const int LUT_SIZE = 256;

vec2 compute_bezier(vec2[NUM_POINTS] points, float t) {
    vec2[NUM_POINTS] intermediates = points;

    for (int i=1; i<NUM_POINTS; i++) {
        for (int j=0; j<NUM_POINTS-i; j++) {
            intermediates[j] = intermediates[j] + (intermediates[j+1] - intermediates[j]) * t;
        }
    }

    return intermediates[0];
}
